def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_pressure = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_pressure += 1
            if opp.get('budget', 0) >= 500:
                rich_aggressive += 1

    if not alive:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 1.0
    if supply <= 16:
        scarcity = 1.35
    elif supply <= 18:
        scarcity = 1.15
    elif supply >= 23:
        scarcity = 0.8
    elif supply >= 21:
        scarcity = 0.9

    urgency = 0.0
    if hp <= 2:
        urgency += 55.0
    elif hp <= 4:
        urgency += 28.0
    elif hp <= 6:
        urgency += 12.0

    if no_water >= 2:
        urgency += 45.0
    elif no_water >= 1:
        urgency += 20.0

    if day >= 8 and hp <= 5:
        urgency += 12.0

    base = 34.0 * scarcity + urgency

    if highest_prev >= 140:
        target = max(base, 86.0 + urgency * 0.35)
    elif highest_prev >= 90:
        target = max(base, min(98.0, avg_prev + 6.0 + urgency * 0.25))
    elif highest_prev >= 55:
        target = max(base, highest_prev + 3.0)
    elif highest_prev > 0:
        target = max(base, highest_prev + 2.0)
    else:
        target = base

    target += desperate_pressure * 3.0
    target += rich_aggressive * 2.0

    if supply >= 23 and hp >= 7 and no_water == 0:
        target *= 0.72
    elif supply >= 21 and hp >= 6 and no_water == 0:
        target *= 0.82

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        keep = min(budget * 0.45, reserve_days * 18.0)
        if hp <= 3 or no_water >= 1:
            keep *= 0.45
        soft_cap = max(0.0, budget - keep)

    if hp <= 2 or no_water >= 2:
        soft_cap = budget

    bid = min(budget, soft_cap if soft_cap > 0 else budget, target)

    if bid < 8.0 and budget >= 8.0:
        bid = 8.0

    if hp <= 2 and bid < 75.0:
        bid = min(budget, 75.0)
    if no_water >= 2 and bid < 88.0:
        bid = min(budget, 88.0)
    if supply <= 16 and (hp <= 4 or no_water >= 1) and bid < 95.0:
        bid = min(budget, 95.0)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_HP = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = 0.0
    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.05
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 7:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.6

    if day_context['supply'] < WATER_REQ * 1.5:
        base_bid *= 1.15
    elif day_context['supply'] >= WATER_REQ * 2:
        base_bid *= 0.9

    strong_opponent_last_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_id in ["Alex", "David"] and opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                strong_opponent_last_bids.append(prev_trace['bid'])

    if strong_opponent_last_bids:
        max_strong_yesterday_bid = max(strong_opponent_last_bids)
        if my_status['hp'] < MAX_HP and base_bid < max_strong_yesterday_bid * 0.95:
            aggressive_bid_target = max_strong_yesterday_bid * 1.05
            base_bid = max(base_bid, min(aggressive_bid_target, DAILY_SALARY * 1.1))
        elif my_status['hp'] == MAX_HP and base_bid < max_strong_yesterday_bid * 0.8:
            base_bid = max(base_bid, max_strong_yesterday_bid * 0.85)

    final_bid = max(1.0, min(my_status['budget'], base_bid))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    max_prev_bid = max(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max_prev_bid * 1.1)
    elif supply < 18:
        bid = min(my_status['budget'], avg_prev_bid * 1.05)
    else:
        bid = min(my_status['budget'], avg_prev_bid * 0.8)

    return float(max(0.0, bid))
